<?php
session_start();require_once __DIR__.'/_auth.php';require_once __DIR__.'/../config/database.php';
function e($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function fotoUrl($foto){$foto=trim((string)$foto);if($foto===''||preg_match('~^(https?:)?//~i',$foto)||strpos(str_replace('\\','/',$foto),'..')!==false)return '';return '../'.ltrim(str_replace('\\','/',$foto),'/');}
$sql="SELECT l.id,l.kategori,l.lokasi,l.deskripsi,l.foto,l.status,l.tanggal,u.nama AS nama_pelapor FROM laporan l LEFT JOIN users u ON l.user_id=u.id ORDER BY l.tanggal DESC,l.id DESC";
$result=mysqli_query($conn,$sql);if(!$result)exit('Gagal mengambil laporan.');$rows=[];$stats=['total'=>0,'Menunggu'=>0,'Diproses'=>0,'Selesai'=>0];while($r=mysqli_fetch_assoc($result)){$rows[]=$r;$stats['total']++;if(isset($stats[$r['status']]))$stats[$r['status']]++;}
?>
