*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#14213d;margin:0;background:#eef2f7}.head{background:#0b1f44;color:white;padding:24px;text-align:center}.head p{color:#dbeafe}.wrap{max-width:1400px;margin:22px auto;padding:0 16px}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:18px}.box{background:white;border:1px solid #dbe3ef;border-top:3px solid #0b1f44;padding:13px;border-radius:8px}.tablebox{background:white;border:1px solid #dbe3ef;border-radius:10px;overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:1050px}th,td{border-bottom:1px solid #dbe3ef;padding:9px;text-align:left;vertical-align:top;font-size:11px}th{background:#e8eef7;color:#0b1f44}.thumb{width:90px;max-height:80px;object-fit:contain}.actions{display:flex;gap:9px;justify-content:center;flex-wrap:wrap;margin:18px}.btn{display:inline-block;border:0;border-radius:8px;padding:11px 15px;text-decoration:none;font-weight:bold;cursor:pointer}.blue{background:#0b1f44;color:white}.light{background:white;color:#0b1f44;border:1px solid #bdcbe0}@media print{body{background:white}.head{print-color-adjust:exact;-webkit-print-color-adjust:exact}.actions{display:none}.wrap{max-width:none;margin:10px 0;padding:0}.summary{grid-template-columns:repeat(4,1fr)}table{min-width:0}th{print-color-adjust:exact;-webkit-print-color-adjust:exact}th,td{font-size:8px;padding:5px}.thumb{width:65px;max-height:60px}}
</style></head><body><div class="head"><h1>REKAP LAPORAN LAPORFASILITAS</h1><p>Dicetak pada <?=date('d-m-Y H:i')?></p></div><main class="wrap"><section class="summary"><?php foreach(['total'=>'Total Laporan','Menunggu'=>'Menunggu','Diproses'=>'Diproses','Selesai'=>'Selesai'] as $k=>$label):?><div class="box"><strong><?=e($label)?></strong><h2><?=$stats[$k]?></h2></div><?php endforeach;?></section>
<div class="tablebox"><table><thead><tr><th>No.</th><th>Pelapor</th><th>Fasilitas</th><th>Lokasi</th><th>Deskripsi</th><th>Foto Kerusakan</th><th>Status</th><th>Tanggal</th></tr></thead><tbody>
<?php foreach($rows as $i=>$r):$src=fotoUrl($r['foto']);?><tr><td><?=$i+1?></td><td><?=e($r['nama_pelapor'])?></td><td><?=e($r['kategori'])?></td><td><?=e($r['lokasi'])?></td><td><?=nl2br(e($r['deskripsi']))?></td><td><?php if($src):?><img class="thumb" src="<?=e($src)?>" alt="Foto kerusakan"><?php else:?>Tidak ada foto<?php endif;?></td><td><?=e($r['status'])?></td><td><?=e($r['tanggal'])?></td></tr><?php endforeach;?>
<?php if(!$rows):?><tr><td colspan="8">Belum ada data laporan.</td></tr><?php endif;?></tbody></table></div>
